const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');
const { parseProfile } = require('../.build/parser');

const service = new ProfileService({ displayName: 'before', tags: ['old'] });
assert.deepEqual(service.patch({ displayName: 'after' }), { displayName: 'after', tags: ['old'] });
assert.deepEqual(service.patch({ tags: ['new'] }), { displayName: 'after', tags: ['new'] });
const storedTags = service.profile.tags;
assert.strictEqual(service.patch({}), service.profile);
assert.strictEqual(service.profile.tags, storedTags);

const input = Object.freeze({ displayName: '  trimmed  ', tags: Object.freeze([' one ', 'two']) });
assert.deepEqual(service.patch(input), { displayName: 'trimmed', tags: ['one', 'two'] });
assert.deepEqual(input.tags, [' one ', 'two']);
assert.notStrictEqual(service.profile.tags, input.tags);
const callerTags = ['three'];
service.patch({ tags: callerTags });
callerTags.push('four');
assert.deepEqual(service.profile.tags, ['three']);
assert.deepEqual(service.patch({ displayName: null, tags: null }), { displayName: null, tags: [] });
assert.deepEqual(service.patch({ tags: [] }), { displayName: null, tags: [] });
assert.deepEqual(service.patch(Object.assign(Object.create(null), { displayName: ' null proto ' })), {
  displayName: 'null proto', tags: [],
});
assert.deepEqual(service.patch({ displayName: 'x'.repeat(40), tags: ['x'.repeat(12), 'a', 'b', 'c', 'd'] }), {
  displayName: 'x'.repeat(40), tags: ['x'.repeat(12), 'a', 'b', 'c', 'd'],
});

const invalid = [
  null, undefined, [], 'name', 1, true, () => {}, new Date(),
  Object.create({ displayName: 'inherited' }),
  { extra: true }, { [Symbol('extra')]: true },
  Object.defineProperty({}, 'extra', { value: true }),
  ...[undefined, 1, false, '', '   ', 'x'.repeat(41)].map(displayName => ({ displayName })),
  ...[undefined, 1, 'tag', {}, [1], [''], ['  '], ['x'.repeat(13)],
    ['a', ' a '], ['a', 'b', 'c', 'd', 'e', 'f'], Array(1)].map(tags => ({ tags })),
  { displayName: 'valid', tags: ['duplicate', ' duplicate '] },
  { displayName: 'valid', unknown: true },
  { displayName: 123, tags: ['valid'] },
];
for (const patch of invalid) {
  const before = { displayName: service.profile.displayName, tags: [...service.profile.tags] };
  const tagsBefore = service.profile.tags;
  assert.throws(() => service.patch(patch), { message: 'invalid profile' });
  assert.deepEqual(service.profile, before);
  assert.strictEqual(service.profile.tags, tagsBefore);
}
assert.deepEqual(parseProfile({}), { displayName: { kind: 'keep' }, tags: { kind: 'keep' } });
assert.deepEqual(parseProfile({ displayName: null, tags: null }), {
  displayName: { kind: 'set', value: null }, tags: { kind: 'set', value: [] },
});
